      const vertices = cachedVertices(withCollapsedClassLinks(drawnGraphRef.current).graph, edgeCurvesRef.current);
      const bounds = canvas.getBoundingClientRect();
      const renderWidth = bounds.width > 0 ? bounds.width : GRAPH_WIDTH;
      const renderHeight = bounds.height > 0 ? bounds.height : GRAPH_HEIGHT;
      const ratio = Math.min(window.devicePixelRatio || 1, 2);
      const nextWidth = Math.max(1, Math.round(renderWidth * ratio));
      const nextHeight = Math.max(1, Math.round(renderHeight * ratio));
